from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class IpInterfaces(SchemaObject):
    interface_name = SchemaField(name='interfaceName')
    ip_address = SchemaField(name='ipAddress')

    def __init__(self, interface_name, ip_address):
        self.interface_name = interface_name
        self.ip_address = ip_address

        super(IpInterfaces, self).__init__()


class Alarm(SchemaObject):
    uuid = SchemaField(name='uuid', not_null=True)
    severity = SchemaField(name='severity', not_null=True)
    alarm_id = SchemaField(name='alarmId', not_null=True)
    alarm_name = SchemaField(name='alarmName', not_null=True)
    fault_id = SchemaField(name='faultId', not_null=True)
    fault_name = SchemaField(name='faultName', not_null=True)

    def __init__(self, uuid, severity, alarm_id, alarm_name, fault_id, fault_name):
        self.uuid = uuid
        self.severity = severity
        self.alarm_id = alarm_id
        self.alarm_name = alarm_name
        self.fault_id = fault_id
        self.fault_name = fault_name

        super(Alarm, self).__init__()


class DistNames(SchemaObject):
    config = SchemaField(name='config', optional=True)
    run_time = SchemaField(name='runtime', optional=True)

    def __init__(self, config, run_time):
        self.config = config
        self.run_time = run_time

        super(DistNames, self).__init__()


class PodsInfoASMV1(SchemaObject):
    alarms = SchemaField(name='alarms', klass=Alarm, many=True)
    availability_status = SchemaField(name='availabilityStatus')
    dist_names = SchemaField(name='distNames', klass=DistNames)
    id = SchemaField(name='id', not_null=True)
    instance = SchemaField(name='instance', not_null=True)
    ip_interfaces = SchemaField(name='ipInterfaces', klass=IpInterfaces, many=True)
    name = SchemaField(name='name')
    operational_state = SchemaField(name='operationalState')

    def __init__(self, instance, id, name, ip_interfaces, availability_status, operational_state, alarms, dist_names):
        self.instance = instance
        self.id = id
        self.name = name
        self.ip_interfaces = ip_interfaces
        self.availability_status = availability_status
        self.operational_state = operational_state
        self.alarms = alarms
        self.dist_names = dist_names

        super(PodsInfoASMV1, self).__init__()
